import {dutyPanel} from './duty-ui.js';
import {workflow,can,timeText,dateText,outcome,DIFFICULTIES,mainWorkDone,SHIFT_END} from './engine.js';

export function plain(value){let s=String(value??'');for(const [a,b] of [
 ['身分交叉核驗','確認是不是約好的人'],['身分核驗','確認身分'],['核驗碼','確認碼'],['指紋讀取器','指紋機'],['讀取器','指紋機'],['虹膜','眼睛掃描'],['覆核','確認'],['核驗','確認'],['查核','確認'],['留置','暫存'],['委派合格代理','請同事幫忙'],['委派','交給同事'],['代理守門人','幫忙的守門人'],['代理','幫忙的同事'],['授權','同意'],['耗材','用品'],['入庫','收進倉庫'],['驗收','點收'],['承辦','負責'],['陳述','說法'],['口述','說的話'],['處置','安排'],['門位感測器','門的感應器'],['門位','門是否關好'],['互鎖','兩扇門不能一起開'],['快取','儲存的資料'],['通報','通知'],['補註','補充紀錄'],['已結案','已完成'],['結案','完成'],['交班事項','上一班的提醒'],['前往門禁控制室','到守門室'],['通訊器','對講機'],['門禁終端','門口電腦'],['工單','報修紀錄']
 ])s=s.split(a).join(b);return s;}

export function actionLabel(action){return {gear:'拿好工作裝備',eat:'吃早餐',sign:'接下這一班',inspectReader:'檢查指紋機',arrivals:'等送貨隊過來',wait:'等同事回覆',closeOuter:'等外門關好',reviewYesterday:'追蹤昨天的箱子',requestRepair:'問工程師能不能修',arrangeCover:'請同事幫忙顧門',waitRepair:'等工程師修好 · 18 分鐘',checkForecast:'看看今天的天氣',callConvoy:'問送貨隊出了什麼事',inspectDrain:'請工程師檢查排水'}[action]||'繼續';}

export function nextButton(s,{b,ui}){const w=workflow(s);if(w.location&&w.location!==s.location)return `<button class="primary" data-move="${w.location}">前往${{dorm:'寢室',canteen:'餐廳',gate:'守門室',engineering:'工程區'}[w.location]} →</button>`;if(w.action)return b(actionLabel(w.action),w.action,'primary');return ui({briefing:'聽上一班交代',terminal:'處理眼前的工作',handover:s.handoverRead?'確認下班':'開始交班',result:'看看今天的結果',standby:'查看待命狀況',incident:'回應新狀況',inventory:'打開置物櫃'}[w.panel]||'繼續',w.panel,'primary');}

export function sceneActions(s,h){const {b,ui}=h;let out=nextButton(s,h);if(s.ended)return out+ui('查看事件簿','journal');if(mainWorkDone(s)&&s.time<SHIFT_END&&!s.activeIncident)return out+b(s.standbyPaused?'繼續待命':'暫停時鐘','toggleStandby')+ui('事件簿','journal');if(s.location==='gate'&&s.readerChecked&&!s.readerClean&&!s.arrived)out+=b('順便清潔指紋機 · 6 分鐘','cleanReader');if(s.location==='engineering')out+=ui('跟工程師聊聊','engineer');if(s.location==='canteen'&&s.ate)out+=ui('跟後勤聊聊','logistics');return out;}

export function briefing(s,{header,c,b,ui,esc}){
 if((s.day||1)>1){laterBriefing(s,{header,c,b,ui,esc});return;}
 header(s.signed?'今天接班時的提醒':'先聽上一班說明','TODAY / START OF SHIFT');
 c.innerHTML=`<p class="lead">${!s.gear?'先拿好工作服和識別證。':!s.ate?'先吃早餐，今天的班從八點開始。':s.signed?'你已經接班了。這裡可以重看上一班的提醒，不會再接一次班。':'上一班的守門人準備下班，先把三件事告訴你。'}</p><div class="speaker"><div class="speaker-icon">上一班</div><div><h3>資深守門人</h3><small>${s.signed?'已完成交接':'等你接手'}</small></div></div><ol class="briefing-list"><li><strong>指紋機有時讀不到。</strong><span>先看看、擦乾淨。還是有問題就記下來，工程師下午會來修。</span></li><li><strong>九點十分有人送貨。</strong><span>約好的是六支濾芯。先確認是誰，再看看東西有沒有對上。</span></li><li><strong>沒問清楚的箱子先別搬進去。</strong><span>可以請後勤保管。下班時，把還沒做完的事交給下一班。</span></li></ol><div class="notice">${s.events.filter(e=>e.category==='待命事件'&&e.status!=='已結案').length?'上一班還有待命事件沒做完，請到事件簿查看負責人與下一步。':'上一班沒有額外的待命事件待辦。'}</div><div class="dialog-actions">${!s.rosterRead&&!can(s,'readRoster')?b('我聽清楚了 · 2 分鐘','readRoster','primary'):!s.rosterRead?`<p class="notice">${esc(can(s,'readRoster'))}</p>`:!s.signed?s.location==='gate'?b('接下這一班 · 08:00','sign','primary'):'<button class="primary" data-move="gate" data-close-move>前往守門室接班 →</button>':ui('回到今天的工作','terminal','primary')}</div>`;
}

export function terminal(s,{header,c,b,ui,esc,actionItem}){
 if(!s.ended&&mainWorkDone(s)&&s.time<SHIFT_END){dutyPanel(s,{header,c,b,ui,esc});return;}
 if((s.day||1)>1){laterTerminal(s,{header,c,b,ui,esc,actionItem});return;}
 header('守門工作','ACCESS CONTROL / B-01');
 if(!s.signed||!s.arrived){c.innerHTML=`<p class="lead">${!s.signed?'先聽上一班交代，再接下這一班。':'先檢查指紋機，等送貨隊過來。'}</p><div class="dialog-actions">${nextButton(s,{b,ui})}</div>`;return;}
 let content='',step='';
 if(s.delegated&&s.delegateDue){step='同事正在幫忙';content=`<p class="lead">同事已接手，會確認人、貨物和多出來的箱子。你可以在這裡等，或去別處走走。</p>${b('等同事回覆','wait','primary')}`;}
 else if(!s.idChecked&&!s.delegated){step='先看看是誰來了';content=`<p class="lead">把眼睛掃描結果和事先約好的資料對一對。指紋機壞掉，不代表對方是假冒的。</p>${b('確認是不是約好的送貨隊 · 3 分鐘','checkId','primary')}`;}
 else if(!s.manifestChecked){step='再看看送來什麼';content=`<p class="lead">人對上了，接著看貨單。今天約好的是六支濾芯。</p>${b('看看貨單和貨物 · 3 分鐘','manifest','primary')}`;}
 else if(!s.standardReceived){step='先收下約好的貨';content=`<p class="lead">六支濾芯和貨單一致，可以先收。多出來的箱子還沒問清楚，先另外放。</p><div class="action-grid">${actionItem('receiveStandard','收下六支濾芯 · 2 分鐘','內門會保持關閉。收完後要等外門關好。')}${actionItem('delegate','請同事接手這批貨 · 22 分鐘','同事會把後面的事情一起處理完。')}</div>`;}
 else if(s.outerGate!=='closed'){step='等外門關好';content=`<p class="lead">約好的貨已收下。外門還在關，不要急著做下一步。</p>${b('等外門完全關上','closeOuter','primary')}`;}
 else if(!s.decision){step='處理多出來的箱子';content=`<p class="lead">${s.medicalReviewed?'醫護確認過了：這箱確實是他們託人帶的，只是忘了先登記。你可以收下，也可以另作安排。':s.medicalRequested?'已經問醫護了，還在等回覆。箱子不會因為你先放好，就自動算處理完。':'這箱沒寫在貨單上。可以先問醫護，也可以暫時放好、退回，或找同事接手。'}</p><div class="action-grid">${!s.claimHeard?actionItem('visitor','問送貨的人這箱是什麼 · 2 分鐘','他的說法會記下來，之後還要找人確認。'):''}${!s.medicalRequested?actionItem('callMedical','問醫護這箱能不能收',`大約 ${s.difficulty==='easy'?12:s.difficulty==='hard'?24:16} 分鐘回覆。`):s.medicalDue?actionItem('wait','等醫護回覆','等待時會推進遊戲時間。'):''}${s.medicalReviewed?actionItem('approve','收下已確認的箱子 · 6 分鐘','後勤點收，並補上登記。'):''}${!s.held?actionItem('hold','請後勤先保管箱子 · 4 分鐘','只是先放好，還沒決定收不收。'):actionItem('leaveHeld','交給下一班繼續處理','把箱子放在哪、還要問誰，一起交代清楚。')}${actionItem('return','把多的箱子退回 · 4 分鐘','已收的六支濾芯不受影響。')}${actionItem('delegate','請同事幫忙處理 · 22 分鐘','同事會問清楚並回報。')}</div><details class="other-options"><summary>其他做法</summary><div class="dialog-actions">${!can(s,'bypass')?ui('還沒問清楚，直接收下…','bypass','danger-button'):''}</div></details>`;}
 else {step='這批貨已安排好';content=`<p class="lead">${s.decision==='held'?'箱子由後勤保管，還要做的事已列給下一班。':'收貨和箱子的處理都有紀錄。'}接下來把工作交給接班同事。</p>${ui('整理今天的工作，準備交班','handover','primary')}`;}
 c.innerHTML=`<div class="work-status"><span>${s.idChecked||s.delegated?'來的人：已確認':'來的人：還沒確認'}</span><span>${s.standardReceived?'約好的貨：已收':'約好的貨：還沒收'}</span><span>內門：關閉</span><span>外門：${s.outerGate==='closed'?'關閉':'關閉中'}</span></div><h3 class="work-step-title">${step}</h3><div class="work-current">${content}</div><details class="device-details"><summary>查看機器上的資料與已做過的事</summary><div class="terminal"><div class="terminal-top"><span>IDENTITY / ${s.idChecked?'MATCHED':'PENDING'}</span><span>CARGO / ${s.medicalReviewed?'REVIEWED':'PENDING'}</span></div><p class="notice">眼睛掃描和預約資料${s.idChecked?'已對上':'還沒確認'}。指紋機有問題，已請工程師處理。醫護只確認貨物，沒有替訪客做健康檢查。</p></div><p class="lead">${s.manifestChecked?'貨單：六支濾芯。現場多一箱醫療用品。':'貨單還沒看。'}${s.held?' 箱子在暫存架 H02，由後勤保管。':''}</p>${ui('查看完整事件紀錄','journal')}</details>`;
}

export function handover(s,{header,c,b,ui,esc}){if(!s.ended&&mainWorkDone(s)&&s.time<SHIFT_END){dutyPanel(s,{header,c,b,ui,esc});return;}if((s.day||1)>1){laterHandover(s,{header,c,b,ui,esc});return;}header(s.handoverRead?'同事確認接手':'下班前，把工作說清楚','END OF SHIFT');const reason=can(s,'reviewHandover');c.innerHTML=`<p class="lead">${s.handoverRead?'接班同事已聽過，也看過紀錄。他知道要接著處理什麼，你可以下班了。':'先把下面三件事交代清楚，再等接班同事答應接手。現在已到下午四點，接班同事來了。把這一班的事情交代清楚。'}</p><ol class="briefing-list"><li><strong>今天收到什麼？</strong><span>${s.standardReceived?'約好的六支濾芯已收下。':'六支濾芯還沒收。'}${s.decision==='approved'?'多的醫療用品也已問清楚並收下。':s.decision==='returned'?'多的箱子已退回。':s.decision==='held'?'多的箱子放在 H02，由後勤保管，還需要下一班繼續問。':s.decision==='delegated'?'同事已幫忙確認並收貨。':s.decision==='bypassed'?'多的箱子沒問清楚就收了，還要說明原因。':'多的箱子還沒安排。'}</span></li><li><strong>門關好了嗎？</strong><span>內門已關閉，外門${s.outerGate==='closed'?'也已關好。':'還在關。'}</span></li><li><strong>還有什麼沒做完？</strong><span>指紋機偶爾讀不到，已請工程師處理。${s.decision==='held'?'下一班要繼續問醫護這箱能不能收。':s.decision==='bypassed'?'下一班要追蹤未經確認的箱子。':'沒有其他未安排的貨物。'}</span></li></ol>${reason?`<div class="notice">${esc(reason)}</div>`:''}<div class="dialog-actions">${!reason?(s.handoverRead?b('確認下班','handover','primary'):b('把這些事交代給接班同事','reviewHandover','primary')):ui('回去完成眼前的工作','terminal','primary')}${ui('看看事件紀錄','journal')}</div>`;}

function laterBriefing(s,{header,c,b,ui,esc}){header('今天上班前，先聽這些','TODAY / '+dateText(s));c.innerHTML=`<p class="lead">${s.day===2?'昨天的工作不是按下班就消失了。今天先追蹤箱子，再安排修指紋機。':'今天午後可能下大雨。送貨隊收到改地點的消息，不能只看代號就相信。'}</p><ol class="briefing-list">${s.day===2?'<li><strong>追蹤昨天的箱子。</strong><span>看看接班同事處理到哪，需不需要你接著問。</span></li><li><strong>工程師可以修指紋機。</strong><span>先問他時間，再找人顧門，不能兩邊都沒人。</span></li>':'<li><strong>先看天氣，再聯絡送貨隊。</strong><span>用原本就知道的聯絡方式問，不用陌生訊息裡新給的號碼。</span></li><li><strong>請工程師看看排水。</strong><span>外面下雨，裡面仍應該乾燥安全。</span></li>'}<li><strong>下班前要有人接手。</strong><span>完成的事、沒做完的事，都要交代清楚。</span></li></ol><div class="notice">${s.events.filter(e=>e.category==='待命事件'&&e.status!=='已結案').length?'上一班還有待命事件沒做完，請到事件簿查看負責人與下一步。':'上一班沒有額外的待命事件待辦。'}</div><div class="dialog-actions">${!s.rosterRead&&!can(s,'readRoster')?b('我聽清楚了 · 2 分鐘','readRoster','primary'):!s.rosterRead?`<div class="notice">${esc(can(s,'readRoster'))}</div>`:!s.signed?s.location==='gate'?b('接下今天這一班','sign','primary'):'<button class="primary" data-move="gate" data-close-move>前往守門室 →</button>':ui('回到今天的工作','terminal','primary')}</div>`;}
function laterTerminal(s,h){const {header,c,b,ui,actionItem}=h;header(s.day===2?'今天：修理與代班':'今天：雨天送貨','TODAY / '+dateText(s));if(!s.signed){c.innerHTML='<p class="lead">先聽上一班交代，再接下今天的工作。</p>'+ui('聽上一班說明','briefing','primary');return;}const w=workflow(s);let extra='';if(s.day===2&&!s.dayDone&&s.yesterdayChecked)extra=actionItem('deferRepair','今天先不修，明天再安排','留下提醒，下一班繼續用眼睛掃描和預約資料。');if(s.day===3&&s.drainChecked&&!s.dayDone){extra=`<div class="action-grid">${actionItem('verifyRoute','再問清楚新地點 · 15 分鐘','確認對方同意，再約交貨時間。')}${actionItem('postponeDelivery','和對方商量改天送 · 4 分鐘','今天物資夠用，明天要再聯絡。')}</div><details class="other-options"><summary>其他做法</summary>${actionItem('acceptMessage','不再確認，直接安排出發','位置可能不清楚，下一班要承擔追蹤。',true)}</details>`;}
 c.innerHTML=`<h3 class="work-step-title">${w.text}</h3>${s.day===3&&s.drainChecked&&!s.dayDone?'':`<div class="dialog-actions">${nextButton(s,{b,ui})}</div>`}${extra}<div class="notice">${s.day===2?(s.readerRepaired?'指紋機已修好。':s.repairDeferred?'維修已留到明天。':'維修期間要有人顧門。'):(s.drainChecked?'排水已確認正常。':'排水還沒檢查。')+' 門內保持乾燥，兩扇門維持關閉。'}</div>${ui('看看今天的紀錄','journal')}`;}
function laterHandover(s,{header,c,b,ui,esc}){header(s.handoverRead?'同事答應接手了':'把今天的工作交代清楚','END OF SHIFT / '+dateText(s));const reason=can(s,'reviewHandover');const summary=s.day===2?(s.readerRepaired?'指紋機修好了，工程師已試過，維修時也有人顧門。':'指紋機留到明天修。下一班還要用眼睛掃描和預約資料確認人。'):s.dayChoice==='verified'?'新交貨點已經問清楚，也約好時間。下一班要追蹤貨物是否按時到。':s.dayChoice==='postponed'?'對方同意改天送，明天需要再聯絡。':'外勤停在安全處等消息，下一班要優先聯絡並確認路線。';c.innerHTML=`<p class="lead">${summary}</p><div class="notice">現在已到下午四點，接班同事來了。把這一班的事情交代清楚。</div><ol class="briefing-list"><li><strong>已完成的事</strong><span>${s.day===2?'昨天的箱子已追蹤，今天的維修已作安排。':'天氣、送貨隊和排水都已確認，送貨方式已記下。'}</span></li><li><strong>留給下一班的事</strong><span>${summary}</span></li><li><strong>安全狀態</strong><span>兩扇門都關好，室內設備持續運作。</span></li></ol>${reason?`<div class="notice">${esc(reason)}</div>`:''}<div class="dialog-actions">${!reason?s.handoverRead?b('確認下班 · 16:00','handover','primary'):b('交代給接班同事','reviewHandover','primary'):ui('回去完成今天的工作','terminal','primary')}${ui('看看事件紀錄','journal')}</div>`;}
export function results(s,{header,c,b,ui,esc}){const o=outcome(s),day=s.day||1;header(day===3?'三天試玩完成':`第 ${day} 天，下班了`,dateText(s));const history=[...(s.history||[]),{day,decision:s.decision||s.dayChoice}];const names={approved:'問清楚後收下',returned:'多的箱子退回',held:'請下一班繼續問',delegated:'同事幫忙完成',bypassed:'沒問清楚就收下',repaired:'修好指紋機',deferred:'維修留到明天',verified:'問清楚新交貨點',postponed:'和對方約改天送',unverified:'外勤正在等消息'};c.innerHTML=`<p class="result-title">${esc(names[s.decision||s.dayChoice]||o.title)}</p><p class="lead">${esc(o.lesson)}</p><div class="result-metrics"><div><label>庇護所健全度</label><strong>${s.health}</strong><small> / 100</small></div><div><label>大家對你的信任</label><strong>${s.trust}</strong><small> / 100</small></div></div><h3 class="section-title">這幾天做過的事</h3><ul class="result-list">${history.map(h=>`<li>第 ${h.day} 天：${esc(names[h.decision]||h.decision)}</li>`).join('')}</ul><div class="notice">${day<3?'今天留下的紀錄與待辦，會帶到隔天。休息後繼續，無需重開遊戲。':'這次只測三天的工作流程，不是全年勝負。可以打開事件簿看完整紀錄，或重玩不同選擇。'}</div><div class="dialog-actions">${day<3?b('休息，繼續第 '+(day+1)+' 天','nextDay','primary'):ui('重玩三天','reset','primary')}${ui('看看事件簿','journal')}<button class="secondary" data-export="session">下載這次的紀錄</button></div>`;}

export function supportPanel(panel,s,{header,c,b,ui,esc,timeline}){
 const day=s.day||1;
 if(panel==='routine'){
  header('指紋機現在怎麼了','MAINTENANCE / '+dateText(s));const e=s.events.find(e=>e.id==='EV-21260916-003');
  const text=s.readerRepaired?'指紋機已修好，工程師也試過了，不用重新報修。':s.repairDeferred?'維修留到今天。工程師忙完後會處理，先用眼睛掃描和預約資料確認身分。':day===2?s.coverArranged?'工程師正在修，同事幫忙顧門。':s.repairRequested?'工程師可以修，先回守門室安排同事顧門。':'今天要安排修指紋機，先問工程師，再找人顧門。':day===3?'指紋機尚待修理，請工程師一併確認。':s.readerChecked?'指紋機有時讀不到，問題已記下。擦乾淨不代表修好了。':'上一班提醒指紋機有時讀不到，接班後先檢查。';
  c.innerHTML=`<p class="lead">${text}</p>${e?timeline(e):'<div class="notice">接班後會開始記錄檢查結果。</div>'}<div class="dialog-actions">${day===1&&s.location==='gate'&&!can(s,'inspectReader')?b('檢查指紋機','inspectReader','primary'):''}${day===1&&s.location==='gate'&&!can(s,'cleanReader')?b('擦乾淨指紋機 · 6 分鐘','cleanReader'):''}${ui('看看今天要做什麼','terminal')}</div>`;return;
 }
 if(panel==='engineer'){
  header('跟工程師聊聊','ENGINEERING / '+dateText(s));const text=s.readerRepaired?'「指紋機修好了，我試過幾次都正常。還有怪狀況再記給我，不用重開一次維修。」':day===1?'「指紋機的問題先幫我記下。擦乾淨後還是讀不到，就別寫成修好了。」':day===2?s.coverArranged?'「有人顧門了，我現在可以修。等我試過再說修好了。」':'「今天可以修，不過要先有人幫你顧門，不能兩邊都空著。」':'「昨天留下的指紋機，我得先處理。排水也會看，但要多等一下。」';
  c.innerHTML=`<p class="spoken">${text}</p><p class="lead">${day===3?'今天也要確認排水溝和抽水設備，讓雨留在外面。':'修理交給工程師，出入口則需要守門人照看。'}</p><div class="dialog-actions">${ui('看看維修紀錄','routine','primary')}${ui('回到今天的工作','terminal')}</div>`;return;
 }
 if(panel==='visitor'){
  header(day===1?'跟送貨的人說話':'對講機','INTERCOM / '+dateText(s));let text;
  if(day===1)text=s.arrived?'「六支濾芯都在。多的這箱是醫療那邊託帶的，你可以問一下。」':'還沒收到預約送貨隊的通知，先完成今天的接班和檢查。';
  else if(day===2)text='今天沒有新的送貨隊在門口。昨天箱子的後續，請問接班同事或後勤。';
  else text=s.dayChoice==='verified'?'新地點已問清楚，時間也約好了。接下來由下一班追蹤貨物。':s.dayChoice==='postponed'?'對方同意改天送。明天要再聯絡，今天不用在門口等。':s.dayChoice==='unverified'?'外勤停在安全處等消息，下一班要優先聯絡。':s.convoyCalled?'熟悉的聯絡人也還沒確認新交貨點。先檢查排水，再決定要多問一次，還是改天送。':'收到改交貨地點的消息。先看天氣，再用原本的聯絡方式問送貨隊。';
  c.innerHTML=`<p class="spoken">${text}</p><div class="dialog-actions">${day===1&&s.arrived&&!can(s,'visitor')?b('把他的說法記下來 · 2 分鐘','visitor','primary'):''}${day===3&&!can(s,'callConvoy')?b('用原本的聯絡方式再問一次','callConvoy','primary'):''}${ui('回到今天的工作','terminal')}</div>`;return;
 }
 header('跟管物資的同事聊聊','SUPPLY / '+dateText(s));let text='「夜班有留飯。今天收貨多出來的東西先跟我說，別堆走道。」';
 if(day===2){const yesterday=s.history?.find(h=>h.day===1)?.decision;text=!s.yesterdayChecked?'「先看看昨天箱子處理到哪，別讓東西只放著、沒人繼續問。」':yesterday==='returned'?'「昨天多的箱子退回了，醫護會再約時間。六支濾芯都收好了。」':'「昨天的箱子都有後續了，你可以在事件簿看到誰接著做了什麼。」';}
 if(day===3)text=s.dayChoice==='postponed'?'「今天物資夠用，已和對方約延後。明天記得再聯絡。」':'「送貨可以先問清楚，今天庫存還夠，不用為了趕時間把人派去不明地點。」';
 c.innerHTML=`<p class="spoken">${text}</p><div class="dialog-actions">${!s.ate&&s.location==='canteen'?b('吃早餐','eat','primary'):''}${ui('看看昨天和今天的紀錄','journal')}</div>`;
}
